<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Mic,Square,Play,Check,ChevronLeft,ChevronRight,Plus,LoaderCircle} from 'lucide-vue-next'
import sentences from '../../../content/sentences.json'
import {rpc,wire,data} from '../transport'
import {notice,play,state} from '../state'
import {stopVoice} from '../speech'
const voices=ref([]),selected=ref(''),records=ref([]),sentence=ref(0),recording=ref(false),saving=ref(false),busy=ref(false),name=ref('Custom voice'),consent=ref(false),showCreate=ref(false)
let recorder,stream,parts=[],timer
const uniqueRecordings=computed(()=>new Set(records.value.map(r=>r.title)).size)
const chosen=computed(()=>voices.value.find(v=>v.id===selected.value))
async function refresh(){try{voices.value=(await rpc('voices.list')).rows||[];if(selected.value)records.value=(await rpc('recordings.list',{tid:selected.value})).rows||[]}catch(e){notice(e.message)}}
async function create(){if(!name.value.trim())return;try{const r=await rpc('voices.create',{text:name.value});voices.value=r.rows;selected.value=r.voice;records.value=[];showCreate.value=false}catch(e){notice(e.message)}}
async function select(v){selected.value=v.id;records.value=(await rpc('recordings.list',{tid:v.id})).rows||[]}
async function preview(v){busy.value=true;try{await play((await rpc('voice.preview',{voice:v.id})).audio)}catch(e){notice(e.message)}finally{busy.value=false}}
async function activate(v){try{await rpc('voices.activate',{voice:v.id});state.voice=v.id;await refresh();notice('Response voice changed.')}catch(e){notice(e.message)}}
async function toggleRecord(){if(recording.value){recorder.stop();return}if(!selected.value||selected.value==='lessac'){notice('Create a custom voice first.');return}if(!consent.value){notice('Confirm that you are recording your own voice.');return}try{stopVoice();stream=await navigator.mediaDevices.getUserMedia({audio:true});parts=[];recorder=new MediaRecorder(stream);const text=sentences[sentence.value];const voiceId=selected.value;recorder.ondataavailable=e=>parts.push(e.data);recorder.onstop=async()=>{recording.value=false;stream.getTracks().forEach(t=>t.stop());saving.value=true;try{const form=new FormData();form.append('file',new Blob(parts,{type:recorder.mimeType}),'recording.webm');form.append('voice_id',voiceId);form.append('text',text);const r=await fetch('/api/uploads/recording',{method:'POST',body:form});if(!r.ok)throw new Error('The recording could not be saved.');wire.decode(await r.arrayBuffer());notice('Recording saved.');await refresh();sentence.value=(sentence.value+1)%sentences.length}catch(e){notice(e.message)}finally{saving.value=false}};recorder.start();recording.value=true;setTimeout(()=>{if(recorder.state==='recording')recorder.stop()},30000)}catch(e){stream?.getTracks().forEach(t=>t.stop());notice('Allow microphone access.')}}
async function train(){busy.value=true;try{const r=await rpc('training.start',{voice:selected.value});notice(r.text);await refresh()}catch(e){notice(e.message)}finally{busy.value=false}}
onMounted(()=>{refresh();timer=setInterval(refresh,8000)});onUnmounted(()=>{clearInterval(timer);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop())})
</script>
<template><div><div class="compact-intro"><div><div class="eyebrow">ADMINISTRATION / VOICES</div><h1>Voice management</h1><p>Record speech and train a response voice.</p></div><button class="button outline" @click="showCreate=!showCreate"><Plus :size="16"/> Create custom voice</button></div><div v-if="showCreate" class="create-voice"><input v-model="name" maxlength="60" aria-label="Voice name" placeholder="Your voice name"><button class="button primary" @click="create">Create</button></div><div class="voice-layout"><div class="record-panel"><div class="record-header"><span>{{chosen?.title||'Select a custom voice'}}</span><span>{{String(sentence+1).padStart(2,'0')}} / {{sentences.length}}</span></div><p class="record-instruction">Read the sentence in your natural speaking voice.</p><blockquote>„{{sentences[sentence]}}“</blockquote><div class="audio-wave" :class="{moving:recording}" aria-hidden="true"><i v-for="i in 36" :key="i" :style="{'--bar':(8+(i*17)%31)+'px','--delay':(i*.04)+'s'}"></i></div><div class="record-controls"><button class="icon-button" :disabled="recording||saving" @click="sentence=Math.max(0,sentence-1)" title="Previous sentence"><ChevronLeft :size="20"/></button><button class="record-button" :disabled="saving" @click="toggleRecord" :aria-label="recording?'Stop recording':'Start recording'"><LoaderCircle v-if="saving" class="spin" :size="23"/><Square v-else-if="recording" :size="22"/><Mic v-else :size="24"/></button><button class="icon-button" :disabled="recording||saving" @click="sentence=(sentence+1)%sentences.length" title="Next sentence"><ChevronRight :size="20"/></button></div><span class="record-label">{{saving?'Saving recording':recording?'Recording':'Ready to record'}}</span><label class="consent"><input v-model="consent" type="checkbox"> I am recording my own voice and want to use it for speech synthesis.</label><div class="record-footer"><span>{{uniqueRecordings}} distinct sentences recorded</span><span>ENGLISH / EN</span></div></div><div><div class="panel voice-library"><div class="panel-heading"><h2>Voice library</h2></div><div v-for="v in voices" :key="v.id" class="voice-row" :class="{selected:selected===v.id}"><button class="voice-select" @click="select(v)"><span class="voice-letter">{{v.title[0]}}</span><span><strong>{{v.title}}</strong><small>{{v.state==='ready'?'Ready':v.state==='recording'?'Collecting recordings':v.state}}</small></span></button><span v-if="data(v).active" class="tag success">Active</span><button v-if="v.state==='ready'" class="icon-button" @click="preview(v)" :disabled="busy" title="Preview voice"><Play :size="17"/></button><button v-if="v.state==='ready'&&!data(v).active" class="icon-button" @click="activate(v)" title="Use voice"><Check :size="17"/></button></div></div><div class="panel training-panel"><h2>Train custom voice</h2><p>Piper is fine-tuned on your recordings. At least 20 distinct, clean recordings are required for an initial run. More material improves quality. CPU training can take a long time.</p><button class="button primary" :disabled="!selected||selected==='lessac'||uniqueRecordings<20||busy||['training','queued'].includes(chosen?.state)" @click="train">Start training</button><RouterLink to="/admin/cache" class="text-link">View background jobs →</RouterLink></div></div></div></div></template>
